                goto fail;
            break;
        }
    } else {
        int diff = ls->addr - bc_out.size - 1;
        if (diff == (int8_t)diff && (op == OP_if_false || op == OP_if_true || op == OP_goto)) {
            jp->size = 1;
            jp->op = OP_if_false8 + (op - OP_if_false);
            dbuf_putc(&bc_out, OP_if_false8 + (op - OP_if_false));
            dbuf_putc(&bc_out, diff);
            break;
